import React, { useEffect, useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import {
  AlertCircle,
  ArrowRight,
  Check,
  ChevronLeft,
  Fingerprint,
  KeyRound,
  Loader2,
  LockKeyhole,
  Mail,
  Moon,
  ShieldCheck,
  Sun,
  UserRound,
} from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import { SEO } from '../components/SEO';
import { useTheme } from '../context/ThemeContext';
import { supabase } from '../lib/supabase';
import './OAuthConsent.css';

type AuthorizationDetailsResponse = Awaited<
  ReturnType<typeof supabase.auth.oauth.getAuthorizationDetails>
>['data'];

type AuthorizationDetails = Extract<
  NonNullable<AuthorizationDetailsResponse>,
  { authorization_id: string }
>;

type PermissionPresentation = {
  title: string;
  description: string;
  icon: LucideIcon;
};

const scopePresentation: Record<string, PermissionPresentation> = {
  openid: {
    title: 'Your Wersee identity',
    description: 'Confirm that it is really you without sharing your password.',
    icon: Fingerprint,
  },
  email: {
    title: 'Email address',
    description: 'Use the verified email address connected to your Wersee account.',
    icon: Mail,
  },
  phone: {
    title: 'Phone number',
    description: 'Use the verified phone number connected to your Wersee account.',
    icon: KeyRound,
  },
  profile: {
    title: 'Basic profile',
    description: 'Read your name and basic Wersee profile information.',
    icon: UserRound,
  },
  offline_access: {
    title: 'Stay connected',
    description: 'Keep the connection active when you are not using the application.',
    icon: LockKeyhole,
  },
};

const getRedirectHost = (redirectUri: string) => {
  try {
    return new URL(redirectUri).host;
  } catch {
    return redirectUri;
  }
};

const getClientInitials = (name: string) => name
  .split(/\s+/)
  .filter(Boolean)
  .slice(0, 2)
  .map((part) => part[0]?.toUpperCase())
  .join('') || 'AP';

const OAuthBackdrop = () => (
  <div className="oauth-consent-ambient" aria-hidden="true">
    <span className="oauth-consent-grid" />
    <span className="oauth-consent-orb is-one" />
    <span className="oauth-consent-orb is-two" />
    <span className="oauth-consent-orb is-three" />
    <span className="oauth-consent-grain" />
  </div>
);

const OAuthBrandBar = ({ onBack }: { onBack?: () => void }) => {
  const { theme, setTheme } = useTheme();
  return (
    <header className="oauth-consent-topbar">
      <button className="oauth-consent-brand" onClick={onBack} aria-label="Back to Wersee">
        <img src="/brand/wersee-icon-192.png" alt="" />
        <span>Wersee</span>
      </button>
      <div className="oauth-consent-secure-pill"><ShieldCheck /> OAuth 2.1 secured</div>
      <button
        className="oauth-consent-theme"
        onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}
        aria-label={`Use ${theme === 'dark' ? 'light' : 'dark'} appearance`}
      >
        {theme === 'dark' ? <Sun /> : <Moon />}
      </button>
    </header>
  );
};

export const OAuthConsent = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const authorizationId = searchParams.get('authorization_id');
  const [authDetails, setAuthDetails] = useState<AuthorizationDetails | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [processingAction, setProcessingAction] = useState<'approve' | 'deny' | null>(null);
  const [signInPath, setSignInPath] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;

    async function loadAuthDetails() {
      if (!authorizationId) {
        if (!cancelled) {
          setError('This authorization request is missing its authorization ID.');
          setLoading(false);
        }
        return;
      }

      try {
        const { data: sessionData } = await supabase.auth.getSession();
        if (!sessionData.session) {
          const consentPath = `/oauth/consent?authorization_id=${encodeURIComponent(authorizationId)}`;
          if (!cancelled) setSignInPath(`/auth?redirect=${encodeURIComponent(consentPath)}`);
          return;
        }

        const { data: userData, error: userError } = await supabase.auth.getUser();
        if (userError) throw userError;

        if (!userData.user) {
          const consentPath = `/oauth/consent?authorization_id=${encodeURIComponent(authorizationId)}`;
          if (!cancelled) setSignInPath(`/auth?redirect=${encodeURIComponent(consentPath)}`);
          return;
        }

        const { data, error: authorizationError } =
          await supabase.auth.oauth.getAuthorizationDetails(authorizationId);

        if (authorizationError) throw authorizationError;
        if (!data) throw new Error('The authorization request could not be found.');

        if (!('authorization_id' in data)) {
          window.location.assign(data.redirect_url);
          return;
        }

        if (!cancelled) setAuthDetails(data);
      } catch (err: unknown) {
        console.error('Error fetching auth details:', err);
        if (!cancelled) {
          setError(err instanceof Error ? err.message : 'Failed to load authorization details');
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    }

    void loadAuthDetails();
    return () => { cancelled = true; };
  }, [authorizationId]);

  async function handleApprove() {
    if (!authorizationId) return;
    setProcessingAction('approve');

    try {
      const { data, error: approvalError } = await supabase.auth.oauth.approveAuthorization(
        authorizationId,
        { skipBrowserRedirect: true },
      );
      if (approvalError) throw approvalError;
      if (!data?.redirect_url) throw new Error('Supabase did not return a redirect URL.');
      window.location.assign(data.redirect_url);
    } catch (err: unknown) {
      console.error('Error approving authorization:', err);
      setError(err instanceof Error ? err.message : 'Failed to approve authorization');
      setProcessingAction(null);
    }
  }

  async function handleDeny() {
    if (!authorizationId) return;
    setProcessingAction('deny');

    try {
      const { data, error: denialError } = await supabase.auth.oauth.denyAuthorization(
        authorizationId,
        { skipBrowserRedirect: true },
      );
      if (denialError) throw denialError;
      if (!data?.redirect_url) throw new Error('Supabase did not return a redirect URL.');
      window.location.assign(data.redirect_url);
    } catch (err: unknown) {
      console.error('Error denying authorization:', err);
      setError(err instanceof Error ? err.message : 'Failed to deny authorization');
      setProcessingAction(null);
    }
  }

  if (loading) {
    return (
      <main className="oauth-consent-page">
        <SEO title="Secure connection" noIndex />
        <OAuthBackdrop />
        <OAuthBrandBar onBack={() => navigate('/')} />
        <section className="oauth-consent-state" role="status" aria-live="polite">
          <div className="oauth-consent-state-icon"><Loader2 className="is-spinning" /></div>
          <p className="oauth-consent-eyebrow">Wersee security</p>
          <h1>Preparing your secure connection</h1>
          <p>Checking the application and requested permissions…</p>
          <div className="oauth-consent-progress"><span /></div>
        </section>
      </main>
    );
  }

  if (error) {
    return (
      <main className="oauth-consent-page">
        <SEO title="Authorization error" noIndex />
        <OAuthBackdrop />
        <OAuthBrandBar onBack={() => navigate('/')} />
        <section className="oauth-consent-state is-error" role="alert">
          <div className="oauth-consent-state-icon"><AlertCircle /></div>
          <p className="oauth-consent-eyebrow">Connection paused</p>
          <h1>We could not finish this request</h1>
          <p>{error}</p>
          <button className="oauth-consent-primary" onClick={() => navigate('/')}>Return to Wersee</button>
        </section>
      </main>
    );
  }

  if (signInPath) {
    return (
      <main className="oauth-consent-page">
        <SEO title="Connect account" noIndex />
        <OAuthBackdrop />
        <OAuthBrandBar onBack={() => navigate('/')} />
        <section className="oauth-consent-state is-signin">
          <div className="oauth-consent-connection-mark" aria-hidden="true">
            <span className="is-wersee"><img src="/brand/wersee-icon-192.png" alt="" /></span>
            <i><b /><b /><b /></i>
            <span className="is-client"><LockKeyhole /></span>
          </div>
          <p className="oauth-consent-eyebrow">Private by design</p>
          <h1>Sign in to review this connection</h1>
          <p>Your password stays with Wersee. You will see every permission before anything is shared.</p>
          <button className="oauth-consent-primary" onClick={() => navigate(signInPath)}>
            Continue with Wersee <ArrowRight />
          </button>
          <button className="oauth-consent-quiet" onClick={() => navigate('/')}>Cancel</button>
        </section>
      </main>
    );
  }

  if (!authDetails) return null;

  const scopes = authDetails.scope?.split(/\s+/).filter(Boolean) || [];
  const clientName = authDetails.client.name;

  return (
    <main className="oauth-consent-page">
      <SEO title={`Connect ${clientName}`} noIndex />
      <OAuthBackdrop />
      <OAuthBrandBar onBack={() => void handleDeny()} />

      <section className="oauth-consent-shell" aria-labelledby="oauth-consent-title">
        <aside className="oauth-consent-story">
          <div className="oauth-consent-story-glow" aria-hidden="true" />
          <div className="oauth-consent-story-top">
            <span className="oauth-consent-story-badge"><ShieldCheck /> Verified Wersee connection</span>
            <div className="oauth-consent-client-orbit" aria-hidden="true">
              <span className="orbit-ring is-outer" />
              <span className="orbit-ring is-inner" />
              <span className="orbit-dot is-one" />
              <span className="orbit-dot is-two" />
              <div className="orbit-core"><img src="/brand/wersee-icon-192.png" alt="" /></div>
              <div className="orbit-client">{getClientInitials(clientName)}</div>
            </div>
          </div>
          <div className="oauth-consent-story-copy">
            <p className="oauth-consent-eyebrow">One account. Your control.</p>
            <h1 id="oauth-consent-title">Connect to {clientName}</h1>
            <p>Wersee shares only the details shown here. Your password, private content and other account data stay out of reach.</p>
          </div>
          <div className="oauth-consent-trust-list">
            <span><LockKeyhole /><b>Encrypted connection</b><small>Protected from request to redirect</small></span>
            <span><ShieldCheck /><b>Revoke any time</b><small>Stay in control from account settings</small></span>
          </div>
        </aside>

        <div className="oauth-consent-request">
          <header className="oauth-consent-request-header">
            <button className="oauth-consent-back" onClick={() => void handleDeny()} disabled={Boolean(processingAction)}>
              <ChevronLeft /> Cancel
            </button>
            <span className="oauth-consent-step">Secure connection</span>
          </header>

          <div className="oauth-consent-request-copy">
            <p className="oauth-consent-eyebrow">Review access</p>
            <h2>Allow this connection?</h2>
            <p><b>{clientName}</b> is requesting the following account details.</p>
          </div>

          <div className="oauth-consent-client-row">
            <span className="oauth-consent-client-logo">{getClientInitials(clientName)}</span>
            <span><b>{clientName}</b><small>{getRedirectHost(authDetails.redirect_uri)}</small></span>
            <em>Verified redirect</em>
          </div>

          {scopes.length ? (
            <div className="oauth-consent-permissions">
              <div className="oauth-consent-permissions-title"><span>Requested access</span><em>{scopes.length} permissions</em></div>
              <ul>
                {scopes.map((scopeItem) => {
                  const permission = scopePresentation[scopeItem] || {
                    title: scopeItem.replaceAll('_', ' '),
                    description: 'Use this requested Wersee permission.',
                    icon: KeyRound,
                  };
                  const PermissionIcon = permission.icon;
                  return (
                    <li key={scopeItem}>
                      <span className="oauth-consent-permission-icon"><PermissionIcon /></span>
                      <span><b>{permission.title}</b><small>{permission.description}</small></span>
                      <span className="oauth-consent-check"><Check /></span>
                    </li>
                  );
                })}
              </ul>
            </div>
          ) : null}

          <div className="oauth-consent-actions">
            <button
              className="oauth-consent-primary"
              onClick={handleApprove}
              disabled={Boolean(processingAction)}
            >
              {processingAction === 'approve' ? <Loader2 className="is-spinning" /> : <ShieldCheck />}
              <span>Continue with Wersee</span>
              {processingAction !== 'approve' ? <ArrowRight /> : null}
            </button>
            <button
              className="oauth-consent-secondary"
              onClick={handleDeny}
              disabled={Boolean(processingAction)}
            >
              {processingAction === 'deny' ? <Loader2 className="is-spinning" /> : null}
              Cancel
            </button>
          </div>

          <p className="oauth-consent-footnote"><LockKeyhole /> Access can be revoked from your Wersee security settings.</p>
        </div>
      </section>
    </main>
  );
};
